const {execFileSync} = require('child_process');
const fs = require('fs');
const EXE='/workspace/dataset/test13_executable';
function run(a,b){
  try{
    const out=execFileSync(EXE,['--a',a,'--b',b],{encoding:'utf8',stdio:['ignore','pipe','ignore']});
    return {out,exit:0};
  }catch(e){
    return {out:(e.stdout||''),exit:(e.status===null?-1:e.status)};
  }
}
const lines=fs.readFileSync('/workspace/probes/type-and-scalars.jsonl','utf8').trim().split('\n').map(JSON.parse);
const idxs=[0,57,193,312,455,588,701,806,899,910].filter(i=>i<lines.length);
let bad=0;
for(const i of idxs){
  const L=lines[i];
  const r=run(L.a,L.b);
  const ok = r.out===L.out && r.exit===L.exit;
  if(!ok){bad++;console.log('MISMATCH line',i+1,JSON.stringify(L),'GOT',JSON.stringify(r));}
  else console.log('ok line',i+1);
}
console.log('bad=',bad);
EOF
